import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Shell from '@/components/layout/Shell';
import { useViewer } from '@/lib/viewer-context';

export default function SignIn() {
  const { signIn } = useViewer();
  const navigate = useNavigate();
  const [handle, setHandle] = useState('');
  const [error, setError] = useState<string | null>(null);

  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!handle.trim()) {
      setError('Enter a handle to sign in.');
      return;
    }
    setError(null);
    signIn();
    navigate('/vault');
  };

  return (
    <Shell>
      <div className="mx-auto max-w-sm px-4 pt-16 md:px-6">
        <h1 className="font-serif text-h2 font-medium text-ink-10">Get back in.</h1>
        <p className="mt-2 text-body-sm text-ink-8">
          Sign in with your handle and the key on your device. No email, no password.
        </p>

        <form onSubmit={submit} noValidate className="mt-8 flex flex-col gap-3">
          <div>
            <label htmlFor="signin-handle" className="block text-body-sm text-ink-9">Handle or address</label>
            <input
              id="signin-handle"
              name="handle"
              type="text"
              value={handle}
              onChange={e => setHandle(e.target.value)}
              placeholder="@handle"
              autoComplete="username"
              required
              aria-invalid={!!error}
              aria-describedby={error ? 'signin-error' : undefined}
              className="mt-1 w-full rounded-md border border-ink-5 bg-ink-2 px-3 py-2.5 font-mono text-body text-ink-10 placeholder:text-ink-7"
            />
          </div>

          {/* honeypot */}
          <input
            type="text"
            name="website_alt"
            tabIndex={-1}
            autoComplete="off"
            aria-hidden="true"
            readOnly
            className="hp-field"
          />

          {error && <p id="signin-error" className="text-body-sm text-rose" role="alert">{error}</p>}

          <button
            type="submit"
            className="mt-2 inline-flex min-h-[44px] items-center justify-center rounded-md bg-mint px-4 py-2.5 text-body-sm font-semibold text-ink-0 hover:bg-mint-dim whitespace-nowrap cursor-pointer"
          >
            Continue
          </button>
        </form>

        <p className="mt-6 text-body-sm text-ink-8">
          No account?{' '}
          <Link to="/join" className="text-ink-10 underline decoration-ink-6 underline-offset-4 hover:text-mint">Create account</Link>
        </p>
      </div>
    </Shell>
  );
}