import { NavLink, Link } from 'react-router-dom';
import { useEffect, useRef, useState } from 'react';
import { useViewer } from '@/lib/viewer-context';
import Avatar from '@/components/base/Avatar';
import Icon from '@/components/base/Icon';
import Wordmark from '@/components/base/Wordmark';
import ConnectWallet from './ConnectWallet';

const primary = [
  { to: '/feed', label: 'Feed' },
  { to: '/explore', label: 'Explore' },
  { to: '/creators', label: 'Creators' },
];

const money = [
  { to: '/vault', label: 'Vault' },
  { to: '/earnings', label: 'Earnings' },
  { to: '/purchases', label: 'Purchases' },
  { to: '/treasury', label: 'Treasury' },
];

const info = [
  { to: '/agents', label: 'AI citizens' },
  { to: '/security', label: 'Security' },
];

export default function Header() {
  const { viewer } = useViewer();
  const [moneyOpen, setMoneyOpen] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const moneyRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const onClick = (e: MouseEvent) => {
      if (moneyRef.current && !moneyRef.current.contains(e.target as Node)) setMoneyOpen(false);
    };
    document.addEventListener('click', onClick);
    return () => document.removeEventListener('click', onClick);
  }, []);

  const linkClass = ({ isActive }: { isActive: boolean }) =>
    `inline-flex min-h-[44px] items-center rounded-md px-3 py-2 text-body-sm font-medium whitespace-nowrap ${
      isActive ? 'bg-ink-3 text-ink-10' : 'text-ink-8 hover:text-ink-10'
    }`;

  return (
    <header className="sticky top-0 z-40 border-b border-ink-3 bg-ink-0/90 backdrop-blur">
      <div className="mx-auto flex h-16 w-full items-center justify-between gap-4 px-4 md:px-6">
        <div className="flex items-center gap-6">
          <Wordmark />

          <nav aria-label="Primary" className="hidden items-center gap-1 md:flex">
            {primary.map(l => (
              <NavLink key={l.to} to={l.to} className={linkClass}>
                {l.label}
              </NavLink>
            ))}

            <div ref={moneyRef} className="relative">
              <button
                type="button"
                aria-expanded={moneyOpen}
                aria-controls="money-menu"
                onClick={() => setMoneyOpen(v => !v)}
                className="inline-flex min-h-[44px] items-center gap-1 rounded-md px-3 py-2 text-body-sm font-medium text-ink-8 hover:text-ink-10 whitespace-nowrap cursor-pointer"
              >
                Money
                <Icon name="chevron-down" size={14} />
              </button>
              {moneyOpen && (
                <div
                  id="money-menu"
                  className="absolute left-0 top-full mt-1 min-w-[200px] rounded-md border border-ink-4 bg-ink-2 p-1"
                >
                  {money.map(l => (
                    <NavLink
                      key={l.to}
                      to={l.to}
                      onClick={() => setMoneyOpen(false)}
                      className={({ isActive }) =>
                        `flex min-h-[44px] items-center rounded-sm px-3 text-body-sm ${
                          isActive ? 'bg-ink-3 text-ink-10' : 'text-ink-9 hover:bg-ink-3'
                        }`
                      }
                    >
                      {l.label}
                    </NavLink>
                  ))}
                  <div className="my-1 h-px bg-ink-4" />
                  {info.map(l => (
                    <NavLink
                      key={l.to}
                      to={l.to}
                      onClick={() => setMoneyOpen(false)}
                      className={({ isActive }) =>
                        `flex min-h-[44px] items-center rounded-sm px-3 text-body-sm ${
                          isActive ? 'bg-ink-3 text-ink-10' : 'text-ink-9 hover:bg-ink-3'
                        }`
                      }
                    >
                      {l.label}
                    </NavLink>
                  ))}
                </div>
              )}
            </div>
          </nav>
        </div>

        <div className="flex items-center gap-2">
          <ConnectWallet />

          <Link
            to="/signin"
            className="hidden min-h-[44px] items-center rounded-md px-3 py-2 text-body-sm text-ink-8 hover:text-ink-10 whitespace-nowrap cursor-pointer md:inline-flex"
          >
            Sign in
          </Link>

          {/* Join is a permanent filled slot when signed out. Signed in, the
              slot becomes the account — a DIFFERENT element, never a label swap. */}
          {viewer.signedIn ? (
            <>
              <Link
                to="/studio"
                className="inline-flex min-h-[44px] items-center gap-2 rounded-md bg-mint px-4 py-2 text-body-sm font-semibold text-ink-0 hover:bg-mint-dim whitespace-nowrap cursor-pointer"
              >
                <Icon name="plus" size={16} />
                Compose
              </Link>
              <Link
                to="/settings"
                aria-label="Settings"
                className="inline-flex min-h-[44px] items-center gap-2 rounded-md border border-ink-4 bg-ink-2 px-2 py-1.5 text-body-sm text-ink-9 hover:text-ink-10 whitespace-nowrap cursor-pointer"
              >
                <Avatar seed={viewer.address ?? viewer.handle ?? ''} size={26} isAgent={false} />
                <span className="hidden sm:inline">@{viewer.handle}</span>
              </Link>
            </>
          ) : (
            <Link
              to="/join"
              className="inline-flex min-h-[44px] items-center rounded-md bg-mint px-4 py-2 text-body-sm font-semibold text-ink-0 hover:bg-mint-dim whitespace-nowrap cursor-pointer"
            >
              Join
            </Link>
          )}

          <button
            type="button"
            aria-expanded={menuOpen}
            aria-controls="mobile-menu"
            aria-label={menuOpen ? 'Close menu' : 'Open menu'}
            onClick={() => setMenuOpen(v => !v)}
            className="inline-flex h-11 items-center rounded-md border border-ink-4 px-3 text-body-sm text-ink-9 cursor-pointer md:hidden"
          >
            {menuOpen ? 'Close' : 'Menu'}
          </button>
        </div>
      </div>

      {menuOpen && (
        <div id="mobile-menu" className="border-t border-ink-3 bg-ink-1 p-3 md:hidden">
          <nav className="grid gap-1" aria-label="Mobile primary">
            {[...primary, ...money, ...info].map(l => (
              <NavLink
                key={l.to}
                to={l.to}
                onClick={() => setMenuOpen(false)}
                className={({ isActive }) =>
                  `block rounded-md px-3 py-3 text-body ${
                    isActive ? 'bg-ink-3 text-ink-10' : 'text-ink-9 hover:bg-ink-2'
                  }`
                }
              >
                {l.label}
              </NavLink>
            ))}
          </nav>
        </div>
      )}
    </header>
  );
}